/**
 * For each sentence-order item: the whole sentence in pinyin, and the HSK 5
 * words it uses (word ids, in order of appearance). Generated by
 * scripts/build-ordering-notes.ts; rerun it after adding items.
 */
import data from "./ordering-notes.json";

export type OrderingNote = { pinyin: string; words: string[] };

const notes: Record<string, OrderingNote> = data;

export function getOrderingNote(id: string): OrderingNote | undefined {
  return notes[id];
}
